def upgrade() -> None:
    bind = op.get_bind()
    op.execute(text('SET LOCAL search_path TO public'))
    existing = inspect(bind)
    for required in REQUIRED_EXISTING:
        if not existing.has_table(required, schema='public'):
            raise RuntimeError(f'KW_SCHEMA_PARENT_MISSING: {required}')
    for table in NEW_TABLES:
        if existing.has_table(table, schema='public'):
            raise RuntimeError(f'KW_SCHEMA_TABLE_ALREADY_EXISTS_REVIEW_REQUIRED: {table}')
    for ddl in TABLE_DDL:
        op.execute(text(ddl))
    for ddl in INDEX_DDL:
        op.execute(text(ddl))
    for ddl in GUARD_DDL:
        op.execute(text(ddl))


def downgrade() -> None:
    # History includes original uploads, external snapshots, and operator decisions.
    # Destructive downgrade is deliberately NOT automated.
    raise RuntimeError('KW_SCHEMA_DOWNGRADE_REQUIRES_EXPLICIT_BACKUP_AND_APPROVAL')
